"""Render all frozen V85 comparisons; no fitting or outcome-dependent selection."""
import csv,json,os,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n')
def main():
    out=ROOT/'results/v85_h2_analysis';data=read(out/'summary.json');raw=read(ROOT/'results/v85_h2_paired/summary.json');assert data['complete']
    cases=data['cases'];flat=[];pairs=[];scenarios=[]
    for c in cases:
        for arm,a in c['arms'].items():
            flat.append({'seed':c['seed'],'arm':arm,'config_id':a['config_id'],'mask':a['config']['mask'],'recompile':a['config']['recompile'],'analyze_sample':a['config']['analyze_sample'],'median_seconds':a['median_seconds'],'range_over_median':a['range_over_median'],'precision_pass':a['precision_pass'],'selection_seconds':a['selection_seconds'],'new_collection_seconds':a['actual_new_branch_collection_seconds'],'logical_evaluations':a['logical_evaluations'],**{f'repeat_{i+1}':v for i,v in enumerate(a['confirmation_seconds'])}})
            for k in ['1','10','100','1000']:
                scenarios.append({'seed':c['seed'],'arm':arm,'serving_suites':int(k),'index_plus_query_seconds':a['index_plus_query_seconds'][k],'modeled_tune_then_serve_seconds':a['modeled_tune_then_serve_seconds'][k]})
        for control in ['rf_lcb','prior']:
            a=c['arms']['llm'];b=c['arms'][control];gain=a['gain_vs_'+control]
            pairs.append({'seed':c['seed'],'control':control,'gain_pct':100*gain,'material_gain':gain>=.1,'precision_pass':a['comparison_precision_vs_'+control],'added_selection_seconds':a['selection_seconds']-b['selection_seconds']})
    for name,rows in [('cases.csv',flat),('paired_differences.csv',pairs),('modeled_deployment.csv',scenarios)]:
        with (out/name).open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    comparisons={}
    for control in ['rf_lcb','prior']:
        p=[r for r in pairs if r['control']==control]
        comparisons[control]={'material_gains':sum(r['material_gain'] for r in p),'precision_qualified_material_gains':sum(r['material_gain'] and r['precision_pass'] for r in p),'precision_pass_cases':sum(r['precision_pass'] for r in p),'mean_paired_gain_pct':statistics.mean(r['gain_pct'] for r in p),'mean_added_selection_seconds':statistics.mean(r['added_selection_seconds'] for r in p),'descriptive_10pct_flags':{'benefit':sum(r['gain_pct']>=10 for r in p),'within_margin':sum(-10<r['gain_pct']<10 for r in p),'harm':sum(r['gain_pct']<=-10 for r in p)}}
    desc={'comparisons':comparisons,'independent_system_groups':1,'seeds':len(cases),'hindsight_non_deployable':True,'deployment_scenarios':'Estimated separate branches; not measured deployment or dollars; K scales the measured 6144-query suite','rf_llm_same_configuration_cases':sum(c['arms']['llm']['config_id']==c['arms']['rf_lcb']['config_id'] for c in cases),'all_selected_masks_match_prior':all(a['config']['mask']==56 for c in cases for a in c['arms'].values()),'llm_incumbents_from_new_proposals':sum(c['arms']['llm']['config_id'] not in [o['config_id'] for o in read(ROOT/f"results/v84_h2_classical/prefix_{c['seed']}.json")['observations']] for c in cases)}
    write(out/'descriptive_summary.json',desc)
    write(ROOT/'artifacts/study_v85_execution/resource_ledger.json',{'new_model_generation_requests':35,'cumulative_model_generation_requests':2156+35,'new_h2_physical_trials':115,'cumulative_h2_physical_trials':184+115,'cumulative_h2_valid_trials':183+115,'cumulative_h2_failed_trials':1,'historical_unattempted_h2_trials':8,'remaining_batch_generations':0,'remaining_batch_physical_trials':0,'historical_prefix_physical_trials_reused':50,'logical_rf_llm_evaluations':200,'logical_prior_evaluations':15,'actual_stage_seconds':data['actual_stage_seconds'],'actual_native_seconds':data['actual_native_seconds'],'actual_selection_seconds':data['actual_selection_seconds'],'model_ledger':raw['ledger'],'usage':data['usage'],'new_download_bytes':0,'cumulative_download_bytes':4817487882,'remaining_download_bytes':551221238,'external_spend_usd':0,'electricity_and_hardware_cost':'unknown','kanzi_physical_trials_unchanged':1265,'rocksdb_physical_trials_unchanged':350,'recorded_table_acquisitions_unchanged':26358})
    cache=ROOT/'.cache/h2-v85-plot';cache.mkdir(parents=True,exist_ok=True);os.environ['MPLCONFIGDIR']=str(cache);os.environ['XDG_CACHE_HOME']=str(cache)
    import matplotlib
    matplotlib.use('Agg');matplotlib.rcParams['svg.hashsalt']='h2-v85'
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,3,figsize=(14,4.5),layout='constrained');colors={'rf_lcb':'#1f77b4','llm':'#c45620','prior':'#247d57'}
    for arm,label,offset in [('rf_lcb','RF-LCB',-.18),('llm','SmolLM3',0),('prior','Fixed prior',.18)]:
        subset=[r for r in flat if r['arm']==arm];x=[i+offset for i in range(5)]
        axes[0].scatter(x,[r['median_seconds'] for r in subset],label=label,color=colors[arm],s=40)
        for i,r in enumerate(subset):axes[0].plot([x[i]]*3,[r[f'repeat_{j}'] for j in [1,2,3]],'_',color=colors[arm],alpha=.55)
        axes[2].plot(range(5),[r['selection_seconds'] for r in subset],marker='o',label=label,color=colors[arm])
    for control,label,marker in [('rf_lcb','vs RF-LCB','o'),('prior','vs fixed prior','s')]:
        p=[r for r in pairs if r['control']==control];axes[1].plot(range(5),[r['gain_pct'] for r in p],marker=marker,label=label)
    axes[1].axhline(10,ls='--',color='gray',label='10% material margin');axes[1].axhline(0,color='gray',lw=.7)
    for ax in axes:ax.set_xticks(range(5),[c['seed'] for c in cases]);ax.set_xlabel('Search seed (same H2 family)');ax.spines[['top','right']].set_visible(False)
    axes[0].set_ylabel('Confirmation query-suite seconds');axes[0].legend(fontsize=8);axes[1].set_ylabel('Relative LLM gain (%)');axes[1].legend(fontsize=8);axes[2].set_ylabel('Selection seconds (seven search choices)')
    fig.suptitle('V85: genuine local model, paired continuation from ten observations\nOne exposed development family; points/repeats are not independent systems')
    fig.savefig(out/'paired_results.png',dpi=170);fig.savefig(out/'paired_results.svg',metadata={'Date':None});plt.close(fig)
    lines=['# V85: real local-model H2 continuation','',f"The frozen batch completed: 35 genuine SmolLM3-3B requests and 115/115 valid fresh H2 trials in {data['actual_stage_seconds']:.3f} seconds. The independent analyzer checked {data['checked_scored_answers']:,} exact scored query answers, reconstructed every RF/model choice, and verified shared prefixes, legal acquired-only prompts, confirmations, order, budgets and provenance.",'',f"At the predeclared 10% margin, LLM material gains were {comparisons['rf_lcb']['material_gains']}/5 versus RF and {comparisons['prior']['material_gains']}/5 versus the cheap prior. After requiring the coarse repeat-precision screen, these counts were {comparisons['rf_lcb']['precision_qualified_material_gains']}/5 and {comparisons['prior']['precision_qualified_material_gains']}/5. Mean paired relative gains were {comparisons['rf_lcb']['mean_paired_gain_pct']:.2f}% and {comparisons['prior']['mean_paired_gain_pct']:.2f}%, respectively; positive means faster. These are descriptive observations, not an equivalence test or independent-system inference.",'','| Seed | RF seconds | LLM seconds | Prior seconds | LLM gain vs RF | LLM gain vs prior | Precision RF/prior |','|---|---:|---:|---:|---:|---:|---|']
    for c in cases:
        a=c['arms'];l=a['llm'];lines.append(f"| {c['seed']} | {a['rf_lcb']['median_seconds']:.6f} | {l['median_seconds']:.6f} | {a['prior']['median_seconds']:.6f} | {100*l['gain_vs_rf_lcb']:.2f}% | {100*l['gain_vs_prior']:.2f}% | {l['comparison_precision_vs_rf_lcb']}/{l['comparison_precision_vs_prior']} |")
    lines+=['','## What ran','', 'All five V84 prefixes (seeds 11,23,37,53,71) were retained. Each RF/LLM arm reused the same ten acquired outcomes, acquired seven search outcomes and spent its final three evaluations confirming a locked incumbent. The standalone prior used three fresh trials per seed. All fresh controls ran with the model resident; the historical prefixes were model-free. Model-selected incumbents absent from the prefix: '+str(desc['llm_incumbents_from_new_proposals'])+'/5. Configurations and every repeat are in `results/v85_h2_analysis/cases.csv`.', '', 'Zero retries, malformed proposals, fallbacks or failed trials occurred. Grammar guaranteed legal unobserved proposals; syntactic validity is not optimization benefit. Temperature zero and requested seeds do not guarantee cross-hardware determinism. Model identity/revision and runtime remain pinned by the unchanged V85 freeze.', '', '## Costs', '', f"Actual collection: {data['actual_native_seconds']:.3f} native-process seconds, {data['actual_selection_seconds']:.3f} selection seconds, {data['model_startup_seconds']:.3f} startup seconds; stage total {data['actual_stage_seconds']:.3f} seconds. Mean added LLM selection time per case: {comparisons['rf_lcb']['mean_added_selection_seconds']:.3f} seconds versus RF and {comparisons['prior']['mean_added_selection_seconds']:.3f} versus the fixed prior. The 50 reused physical prefix trials retain their historical costs; they are not new collection. New logical charges total 215 including both branches' prefixes and the standalone prior.", '', f"Observed token accounting: {json.dumps(data['usage'],sort_keys=True)}. HTTP requests including health/template/tokenization: {data['http_requests']}; generation calls: 35. New downloads 0; external spending USD 0. Electricity and hardware costs unknown.", '', '`modeled_deployment.csv` reports the frozen K={1,10,100,1000} index-plus-query and tuning-plus-serving scenarios. One K unit is the measured 6144-query suite. Each selected branch includes its historical prefix, own fresh trials and decisions; LLM includes cold startup per hypothetical deployment. These are estimates, not actual deployment measurements. Do not sum per-case cold starts into actual batch costs.', '', '## Interpretation and limits', '', 'H2 is one exposed development system on one generated in-memory workload and one machine. Five seeds cannot establish cross-system generalization; three confirmations and the range/median screen cannot prove equivalence. The strong predicate-index prior may leave limited headroom. Query time excludes setup/index construction; the separate deployment scenarios expose that accounting choice. All final configurations used the prior’s index mask 56; RF and LLM selected exactly the same configuration in four of five seeds. Differences in those four pairs are timing variation, not different final configurations. One RF confirmation set (seed 11) failed the coarse precision screen (range/median 20.75%); it remains included and flagged.', '', 'This does not establish a useful learned escalation controller or Q2 readiness. Hindsight min(RF,LLM) is retained only as a nondeployable diagnostic. Do not fit a router or select prompts/seeds using these outcomes. Stronger-model robustness, independent realistic workloads, clean-machine native replication and defensible novelty remain untested.', '', '## Reproduce and inspect', '', 'Raw requests, completions, tokens, native receipts, outputs and costs: `results/v85_h2_paired/`. Validated summary, repeats and figures: `results/v85_h2_analysis/`. Authorization and cumulative ledger: `artifacts/study_v85_execution/`. Frozen method: `reports/protocol_v85.md`. Post-run full suite: 625 tests passed in 22.11 seconds (`artifacts/study_v85_execution/tests_all.log`), including six explicit synthetic analyzer tests; synthetic data never enter these aggregates.', '', 'Read-only semantic replay: `.venv/bin/python -c "import sys; sys.path.insert(0,\'scripts\'); from analyze_h2_v85 import analyze; print(analyze()[\'complete\'])"`. Regenerate figures/tables with `.venv/bin/python scripts/report_h2_v85.py`. Fresh collection is not part of replay and the approved inference allowance is now exhausted.','']
    (ROOT/'reports/h2_v85.md').write_text('\n'.join(lines));print(json.dumps(desc,indent=2))
if __name__=='__main__':main()
